@section('scripts')<script>document.querySelectorAll('[data-upload]').forEach(form=>form.addEventListener('submit',()=>{const button=form.querySelector('button[type=submit]:not([form])');button.disabled=true;button.textContent='جارٍ الحفظ والرفع…';const status=form.querySelector('.upload-status');if(status)status.textContent='انتظر اكتمال الرفع، ولا تغلق الصفحة.';}));window.addEventListener('pageshow',()=>document.querySelectorAll('[data-upload] button[type=submit]:not([form])').forEach(button=>{if(button.disabled){button.disabled=false;button.textContent='إعادة المحاولة';}}));</script>@endsection
